package net.mpy.vm;

import net.mpy.compiler.MpyCross;
import net.mpy.loader.MpyLoader;
import net.mpy.loader.MpyModule;
import net.mpy.qstr.QstrPool;
import net.mpy.qstr.SymbolMap;
import net.mpy.qstr.SymbolPool;
import net.mpy.runtime.PyObj;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class SymbolTest {
    @Test void readsSnapshotProducedByThePreviousLinkedHashMapImplementation() throws Exception {
        // Generated by the pre-symbol p9 JAR, SHA256
        // 2e5f4a0d8687eb4968b2a6ceac8f39c8cbb2ef14650ae0ee412feb9fe66b8dec.
        // It contains a suspended LegacyRecord instance, its bound callback and
        // a continuation that checks order, dynamic setattr and callback dispatch.
        byte[] encoded;
        try (var input = getClass().getResourceAsStream("/legacy-symbol-snapshot.b64")) {
            assertNotNull(input);
            encoded = input.readAllBytes();
        }
        Vm vm = new Vm(null);
        for (int i = 0; i < 25; i++) vm.symbols.intern("new-runtime-name-" + i);
        vm.restoreSnapshot(java.util.Base64.getMimeDecoder().decode(encoded));
        finish(vm);
        assertEquals(true, vm.globals.get("passed"));
        assertEquals(29L, ((PyInstance) vm.globals.get("obj")).attrs.get("value"));
        assertDoesNotThrow(() -> { Vm.fromSnapshot(vm.saveSnapshot()); });
    }

    private static MpyModule compile(String source) {
        return MpyLoader.load(MpyCross.compile(source, "symbols.py"), new QstrPool());
    }
    private static Vm start(String source, String... modules) {
        MpyModule code = compile(source);
        Vm vm = new Vm(code);
        vm.setCompiler((text, filename, mode) -> MpyCross.compile(text, filename));
        Map<String, byte[]> files = new HashMap<>();
        for (int i = 0; i < modules.length; i += 2)
            files.put(modules[i], MpyCross.compile(modules[i + 1], modules[i] + ".py"));
        vm.setModuleFinder(files::get);
        vm.start(new Frame(code.root));
        return vm;
    }
    private static void finish(Vm vm) {
        for (int i = 0; i < 10000 && !vm.isFinished(); i++) vm.step(new int[] {1000});
        assertTrue(vm.isFinished());
    }

    @Test void orderedStringFacadeAndViewsSurviveBindingToAnotherPool() {
        SymbolMap map = new SymbolMap();
        map.put(new String("FB"), 1L); // same String.hashCode as Ea
        map.put(new String("Ea"), 2L);
        map.put("nullable", null);
        var keys = map.keySet();
        var values = map.values();
        var entries = map.entrySet();
        SymbolPool pool = new SymbolPool();
        pool.intern("different-order");
        map.bind(pool);
        assertEquals(1L, map.get(new String("FB")));
        assertEquals(2L, map.getSymbol(pool, pool.find("Ea")));
        assertTrue(map.containsKey("nullable"));
        assertFalse(map.containsKey("missing"));
        assertNull(map.get("missing"));
        assertEquals(0, pool.find("missing"));
        map.put("FB", 3L);
        map.remove("Ea");
        map.put("Ea", 4L);
        assertEquals(List.of("FB", "nullable", "Ea"), new ArrayList<>(keys));
        assertEquals(java.util.Arrays.asList(3L, null, 4L), new ArrayList<>(values));
        var iterator = entries.iterator();
        assertEquals(3L, iterator.next().setValue(5L));
        iterator.remove();
        assertFalse(map.containsKey("FB"));
        values.remove(4L);
        assertEquals(List.of("nullable"), new ArrayList<>(keys));
        map.clear();
        assertTrue(values.isEmpty());
    }

    @Test void modulesAndDynamicNamesShareIdsWithoutInterningDataStrings() {
        Vm vm = start("""
                import records
                import accessor
                obj = records.Record()
                obj.value = 10
                obj.FB = 1
                obj.Ea = 2
                dynamic = ''.join(['va', 'lue'])
                assert getattr(obj, dynamic) == 10
                setattr(obj, dynamic, 20)
                assert accessor.increment(obj) == 42
                assert list(obj.__dict__) == ['value', 'FB', 'Ea']
                delattr(obj, 'FB')
                obj.FB = 3
                assert list(obj.__dict__) == ['value', 'Ea', 'FB']
                accessor.increment.note = 'function-data-only-1287'
                assert getattr(accessor.increment, ''.join(['no', 'te'])) == 'function-data-only-1287'
                setattr(accessor, 'dynamic_export', obj)
                assert accessor.dynamic_export is obj
                assert records.Record.shared == 9
                payload = 'ordinary-string-only-3846'
                mapping = {'ordinary-dict-key-only-3846': payload}
                for i in range(100):
                    assert not hasattr(obj, 'missing_dynamic_' + str(i))
                ns = {'obj': obj}
                exec('obj.value = 40', ns)
                assert obj.value == 40
                passed = True
                """, "records", """
                padding = 'padding value'
                class Base:
                    @property
                    def doubled(self):
                        return self.value * 2
                class Record(Base):
                    shared = 9
                """, "accessor", """
                def increment(record):
                    record.value += 1
                    return record.doubled
                """);
        finish(vm);
        assertEquals(true, vm.globals.get("passed"));
        PyInstance obj = (PyInstance) vm.globals.get("obj");
        int id = vm.symbols.find("value");
        assertTrue(id > 0);
        assertSame(vm.symbols, obj.attrs.symbols());
        assertSame(vm.symbols, obj.cls.ns.symbols());
        assertSame(vm.symbols, obj.cls.bases[0].ns.symbols());
        assertEquals(40L, obj.attrs.getSymbol(vm.symbols, id));
        for (PyModule module : vm.loadedModules.values()) assertSame(vm.symbols, module.ns.symbols());
        for (String data : List.of("ordinary-string-only-3846", "ordinary-dict-key-only-3846", "function-data-only-1287", "missing_dynamic_99"))
            assertEquals(0, vm.symbols.find(data), data);
    }

    @Test void sharedBytecodeCanExecuteInTwoIndependentSymbolSpaces() {
        MpyModule code = compile("""
                class Record:
                    def read(self):
                        return self.unique_attribute
                obj = Record()
                obj.unique_attribute = 73
                result = obj.read()
                """);
        Vm first = new Vm(code), second = new Vm(code);
        second.symbols.intern("second-vm-only");
        first.start(new Frame(code.root));
        second.start(new Frame(code.root));
        for (int i = 0; i < 10000 && (!first.isFinished() || !second.isFinished()); i++) {
            if (!first.isFinished()) first.step();
            if (!second.isFinished()) second.step();
        }
        assertTrue(first.isFinished() && second.isFinished());
        assertEquals(73L, first.globals.get("result"));
        assertEquals(73L, second.globals.get("result"));
        assertNotEquals(first.symbols.find("unique_attribute"), second.symbols.find("unique_attribute"));
        assertEquals(0, first.symbols.find("second-vm-only"));
        assertSame(first.symbols, ((PyInstance) first.globals.get("obj")).attrs.symbols());
        assertSame(second.symbols, ((PyInstance) second.globals.get("obj")).attrs.symbols());
    }

    @Test void snapshotRemapsIdsAndPreservesAttributeOrderCallbacksAndExceptions() {
        Vm original = start("""
                import model
                obj = model.Record()
                obj.value = 6
                obj.tail = 9
                callback = obj.read
                error = model.Failure('message')
                error.detail = obj
                armed = True
                yieldJava()
                assert callback() == 6
                assert error.detail is obj
                assert list(obj.__dict__) == ['value', 'tail']
                obj.value = 8
                assert callback() == 8
                passed = True
                """, "model", """
                class Record:
                    def read(self):
                        return self.value
                class Failure(Exception):
                    pass
                """);
        for (int i = 0; i < 10000 && !Boolean.TRUE.equals(original.globals.get("armed")); i++) original.step();
        assertEquals(true, original.globals.get("armed"));
        byte[] saved = original.saveSnapshot();
        Vm restored = new Vm(null);
        for (int i = 0; i < 37; i++) restored.symbols.intern("restore-padding-" + i);
        restored.restoreSnapshot(saved);
        finish(restored);
        assertEquals(true, restored.globals.get("passed"));
        assertNotEquals(original.symbols.find("value"), restored.symbols.find("value"));
        assertSame(restored.symbols, ((PyInstance) restored.globals.get("obj")).attrs.symbols());
        assertDoesNotThrow(() -> { restored.saveSnapshot(); });
    }

    @Test void hostNamespacesStayLiveAndUseTheReceivingVmPool() {
        MpyModule code = compile("""
                assert host.value == 1
                host.value = 2
                assert getattr(host, ''.join(['va', 'lue'])) == 2
                remote = make_module()
                setattr(remote, 'value', 3)
                assert remote.value == 3
                passed = True
                """);
        PyModule host = new PyModule("host", "", null);
        host.ns.put("value", 1L);
        PyModule remote = new PyModule("remote", "", null);
        Map<String, Object> globals = new HashMap<>();
        globals.put("host", host);
        globals.put("make_module", (HostFunction) args -> remote);
        Vm vm = new Vm(code, globals);
        vm.start(new Frame(code.root));
        finish(vm);
        assertEquals(true, globals.get("passed"));
        assertEquals(2L, host.ns.get("value"));
        assertSame(vm.symbols, host.ns.symbols());
        assertSame(vm.symbols, remote.ns.symbols());
    }

    @Test void retainedSymbolsAreIncludedInMemoryAccountingEvenAfterAttributeDeletion() {
        Vm vm = start("class Record:\n    pass\nobj = Record()\n");
        finish(vm);
        PyInstance obj = (PyInstance) vm.globals.get("obj");
        long before = vm.estimatedMemory();
        String name = "runtime_name_" + "x".repeat(2048);
        obj.attrs.put(name, PyObj.NONE);
        obj.attrs.remove(name);
        assertTrue(vm.estimatedMemory() >= before + 4096);
        assertTrue(vm.symbols.find(name) > 0);
        assertFalse(obj.attrs.containsKey(name));
    }
}
